def trang_thai_to_enum(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        return
    with schema_editor.connection.cursor() as cursor:
        for table, enum_type, labels, default in ENUM_COLUMNS:
            cursor.execute("SELECT 1 FROM pg_type WHERE typname = %s", [enum_type])
            if cursor.fetchone() is None:
                values = ", ".join("'%s'" % label for label in labels)
                cursor.execute(f"CREATE TYPE {enum_type} AS ENUM ({values})")
            cursor.execute(
                "SELECT udt_name FROM information_schema.columns "
                "WHERE table_schema = current_schema() AND table_name = %s AND column_name = 'trang_thai'",
                [table],
            )
            if cursor.fetchone()[0] != enum_type:
                cursor.execute(f"ALTER TABLE {table} ALTER COLUMN trang_thai DROP DEFAULT")
                cursor.execute(
                    f"ALTER TABLE {table} ALTER COLUMN trang_thai TYPE {enum_type} USING trang_thai::{enum_type}"
                )
                cursor.execute(f"ALTER TABLE {table} ALTER COLUMN trang_thai SET DEFAULT '{default}'")


